"""Validation rules migrated from legacy/order_rules.vrl."""

from decimal import Decimal
from typing import Any


def _value(record: dict | None, column: str) -> Any:
    """Return a field value, treating a missing record or key as empty."""
    if record is None:
        return ""
    return record.get(column, "")


def _number(value: Any) -> Decimal:
    """Apply the legacy empty-string-to-zero numeric coercion."""
    if value == "":
        return Decimal(0)
    return Decimal(str(value))


def _lookup(
    tables: dict | None,
    table_name: str,
    key_column: str,
    key_value: Any,
    output_column: str,
) -> Any:
    """Perform a legacy LOOKUP, ignoring soft-deleted rows."""
    if tables is None:
        return ""

    rows = tables.get(table_name, [])
    for row in rows:
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get(key_column, "") == key_value:
            return row.get(output_column, "")
    return ""


def _failure(code: str, message: str) -> dict:
    return {
        "code": code,
        "message": message,
        "severity": "BLOCK",
    }


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    tables: dict | None = None,
    table: str = "ORD_HEADER",
) -> list[dict]:
    """Run applicable order rules in legacy rule-file order."""
    errors: list[dict] = []

    if table == "ORD_HEADER":
        # ORD-001
        if event in ("INSERT", "UPDATE"):
            discount = _number(_value(record, "DISC_PCT"))
            if not (discount >= Decimal(0) and discount <= Decimal(100)):
                errors.append(
                    _failure("E5001", "Discount out of range")
                )

        # ORD-002
        if event == "UPDATE":
            discount = _number(_value(record, "DISC_PCT"))
            rule_passes = True
            if discount > Decimal(20):
                role = _lookup(
                    tables,
                    "USR_MASTER",
                    "USR_ID",
                    _value(record, "OWNER_UID"),
                    "ROLE_ID",
                )
                rule_passes = role == "MGR" or role == "ADMIN"

            if not rule_passes:
                errors.append(
                    _failure(
                        "E5002",
                        "Discount over 20 percent requires manager role",
                    )
                )

        # ORD-003
        if event == "UPDATE":
            old_status = _value(old, "STAT_CD")
            new_status = _value(record, "STAT_CD")
            rule_passes = not (
                old_status == "I"
                and new_status != "I"
                and new_status != "X"
            )
            if not rule_passes:
                errors.append(
                    _failure(
                        "E5003",
                        "Invoiced order can only be cancelled",
                    )
                )

    elif table == "ORD_LINE":
        # ORD-004
        if event in ("INSERT", "UPDATE"):
            quantity = _number(_value(record, "QTY"))
            if not quantity > Decimal(0):
                errors.append(
                    _failure("E5004", "Quantity must be positive")
                )

        # ORD-005
        if event == "INSERT":
            active_flag = _lookup(
                tables,
                "PROD_MASTER",
                "PROD_ID",
                _value(record, "PROD_ID"),
                "ACTIVE_FLG",
            )
            if active_flag != "Y":
                errors.append(
                    _failure("E5005", "Product not active")
                )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any collected failure has BLOCK severity."""
    return any(error.get("severity") == "BLOCK" for error in errors)
